import { getImageProps } from "next/image"

export default function Home() {
  const common = { alt: "Menyu banneri", sizes: "100vw" }
  const { props: { srcSet: desktop } } = getImageProps({ ...common, src: "/wide.jpg", width: 1600, height: 600 })
  const { props: { srcSet: mobile, ...rest } } = getImageProps({ ...common, src: "/tall.jpg", width: 600, height: 900 })
  return (
    <picture>
      <source media="(min-width: 768px)" srcSet={desktop} />
      <source srcSet={mobile} />
      <img {...rest} style={{ width: "100%", height: "auto" }} />
    </picture>
  )
}

